BEGIN;

SET LOCAL lock_timeout = '5s';

CREATE SCHEMA rp1_monitor;

REVOKE ALL ON SCHEMA rp1_monitor FROM PUBLIC;

SET LOCAL search_path = rp1_monitor, pg_catalog;

CREATE TABLE monitor_policy_versions (
	policy_sha256 TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (policy_sha256)
);

CREATE TABLE monitor_robots (
	robot_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	source_kind TEXT NOT NULL, 
	token_digest TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	joint_names JSONB, 
	PRIMARY KEY (robot_id), 
	CONSTRAINT ck_monitor_robot_source CHECK (source_kind IN ('simulated','ros2')), 
	CONSTRAINT ck_monitor_token_digest CHECK (length(token_digest) = 64), 
	UNIQUE (token_digest)
);

CREATE TABLE monitor_alert_events (
	id BIGSERIAL NOT NULL, 
	robot_id TEXT NOT NULL, 
	rule_key TEXT NOT NULL, 
	occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	event_kind TEXT NOT NULL, 
	policy_sha256 TEXT NOT NULL, 
	evidence JSONB NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_monitor_alert_event CHECK (event_kind IN ('opened','recovered','observation_lost','observation_restored')), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id), 
	FOREIGN KEY(policy_sha256) REFERENCES monitor_policy_versions (policy_sha256)
);

CREATE INDEX ix_monitor_alert_events_policy ON monitor_alert_events (policy_sha256);

CREATE INDEX ix_monitor_alert_events_robot_id ON monitor_alert_events (robot_id, id);

CREATE TABLE monitor_alert_heads (
	robot_id TEXT NOT NULL, 
	rule_key TEXT NOT NULL, 
	state TEXT NOT NULL, 
	is_open BOOLEAN NOT NULL, 
	condition_since TIMESTAMP WITH TIME ZONE, 
	opened_at TIMESTAMP WITH TIME ZONE, 
	evaluated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	policy_sha256 TEXT NOT NULL, 
	evidence JSONB NOT NULL, 
	PRIMARY KEY (robot_id, rule_key), 
	CONSTRAINT ck_monitor_alert_state CHECK (state IN ('normal','pending','active','unknown')), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id), 
	FOREIGN KEY(policy_sha256) REFERENCES monitor_policy_versions (policy_sha256)
);

CREATE INDEX ix_monitor_alert_open ON monitor_alert_heads (robot_id, evaluated_at) WHERE is_open IS true;

CREATE INDEX ix_monitor_alert_policy ON monitor_alert_heads (policy_sha256);

CREATE TABLE monitor_archive_manifests (
	archive_id TEXT NOT NULL, 
	robot_id TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	window_start TIMESTAMP WITH TIME ZONE NOT NULL, 
	window_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	high_water_id BIGINT NOT NULL, 
	windows BIGINT NOT NULL, 
	compressed_bytes BIGINT NOT NULL, 
	sha256 TEXT NOT NULL, 
	file_name TEXT NOT NULL, 
	PRIMARY KEY (archive_id), 
	CONSTRAINT uq_monitor_archive_file UNIQUE (file_name), 
	CONSTRAINT ck_monitor_archive_range CHECK (window_end > window_start AND windows > 0 AND compressed_bytes > 0), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE INDEX ix_monitor_archive_robot_time ON monitor_archive_manifests (robot_id, window_start);

CREATE TABLE monitor_daily_usage (
	robot_id TEXT NOT NULL, 
	received_day TIMESTAMP WITH TIME ZONE NOT NULL, 
	windows BIGINT NOT NULL, 
	raw_json_bytes BIGINT NOT NULL, 
	key_json_bytes BIGINT NOT NULL, 
	PRIMARY KEY (robot_id, received_day), 
	CONSTRAINT ck_monitor_usage_nonnegative CHECK (windows >= 0 AND raw_json_bytes >= 0 AND key_json_bytes >= 0), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE INDEX ix_monitor_usage_day ON monitor_daily_usage (received_day);

CREATE TABLE monitor_diagnostic_records (
	report_id TEXT NOT NULL, 
	robot_id TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	sha256 TEXT NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (report_id), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE INDEX ix_monitor_diagnostics_robot_time ON monitor_diagnostic_records (robot_id, created_at);

CREATE TABLE monitor_latest (
	robot_id TEXT NOT NULL, 
	stream_id TEXT NOT NULL, 
	sequence BIGINT NOT NULL, 
	stream_first_seen TIMESTAMP WITH TIME ZONE NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	payload JSONB NOT NULL, 
	PRIMARY KEY (robot_id), 
	CONSTRAINT ck_monitor_latest_sequence CHECK (sequence > 0), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE TABLE monitor_relay_status (
	robot_id TEXT NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	observed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	session_id TEXT NOT NULL, 
	sequence BIGINT NOT NULL, 
	payload JSONB NOT NULL, 
	PRIMARY KEY (robot_id), 
	CONSTRAINT ck_monitor_relay_sequence CHECK (sequence > 0), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE TABLE monitor_windows (
	id BIGSERIAL NOT NULL, 
	robot_id TEXT NOT NULL, 
	stream_id TEXT NOT NULL, 
	sequence BIGINT NOT NULL, 
	window_start TIMESTAMP WITH TIME ZONE NOT NULL, 
	window_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	payload_hash TEXT NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_monitor_window UNIQUE (robot_id, stream_id, sequence), 
	CONSTRAINT ck_monitor_window_range CHECK (sequence > 0 AND window_end > window_start), 
	CONSTRAINT ck_monitor_window_hash CHECK (length(payload_hash) = 64), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id)
);

CREATE INDEX ix_monitor_robot_time ON monitor_windows (robot_id, window_end);

CREATE INDEX ix_monitor_windows_retention ON monitor_windows USING brin (window_end);

CREATE INDEX ix_monitor_windows_robot_id ON monitor_windows (robot_id);

CREATE TABLE monitor_key_windows (
	window_id BIGINT NOT NULL, 
	robot_id TEXT NOT NULL, 
	window_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	policy_sha256 TEXT NOT NULL, 
	metrics JSONB NOT NULL, 
	json_bytes BIGINT NOT NULL, 
	PRIMARY KEY (window_id), 
	CONSTRAINT ck_monitor_key_bytes CHECK (json_bytes >= 0), 
	FOREIGN KEY(window_id) REFERENCES monitor_windows (id), 
	FOREIGN KEY(robot_id) REFERENCES monitor_robots (robot_id), 
	FOREIGN KEY(policy_sha256) REFERENCES monitor_policy_versions (policy_sha256)
);

CREATE INDEX ix_monitor_key_policy ON monitor_key_windows (policy_sha256);

CREATE INDEX ix_monitor_key_robot_time ON monitor_key_windows (robot_id, window_end);

COMMIT;
